    @Test
    void pixComMaisDeUmaParcelaRetornaParcelamentoInvalido() {
        CheckoutRequest request = new CheckoutRequest(
                List.of(new ItemPedido("Camiseta", new BigDecimal("79.90"), 1, new BigDecimal("0.30"))),
